package com.example.billing.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.*;
@Entity @Table(name="Payments",uniqueConstraints=@UniqueConstraint(name="IX_Payments_IdempotencyKey",columnNames="IdempotencyKey"),indexes=@Index(name="IX_Payments_InvoiceId",columnList="InvoiceId")) public class Payment { @Id @Column(name="Id") public UUID id; @Column(name="InvoiceId",nullable=false) public UUID invoiceId; @Column(name="Amount",precision=18,scale=2,nullable=false) public BigDecimal amount; @Column(name="Status",length=50,nullable=false) public String status; @Column(name="Provider",length=100,nullable=false) public String provider; @Column(name="IdempotencyKey",length=200,nullable=false) public String idempotencyKey; @Column(name="CreatedAt",nullable=false) public OffsetDateTime createdAt; @OneToMany(mappedBy="payment",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("attemptNumber") public List<PaymentAttempt> attempts=new ArrayList<>(); }
